using LobbyEmulator.Utils;
using System;
using System.Collections.Generic;

namespace LobbyEmulator.Logic
{
  internal class LobbyPreData : IPacketReader
  {
    public int Port { get; } = 9001;
    public bool Init { get; set; }

    byte[] remaindData = new byte[0];

    public List<byte[]> HandlePacket(byte[] pack)
    {
      List<byte[]> result = new List<byte[]>();

      if (remaindData.Length > 0)
      {
        byte[] newArray = new byte[remaindData.Length + pack.Length];
        Array.Copy(remaindData, 0, newArray, 0, remaindData.Length);
        Array.Copy(pack, 0, newArray, remaindData.Length, pack.Length);
        pack = newArray;

        remaindData = new byte[0];
      }

      Packet packParser = Packet.Parse(pack);
      if (packParser.Completeness == PComplet.Incomplete)
      {
        remaindData = pack;
        return result;
      }

      while (packParser.Completeness == PComplet.Complete || packParser.Completeness == PComplet.CompleteWithRemainder)
      {
        result.AddRange(HandlePacketInternal(packParser));

        if (packParser.Completeness == PComplet.Complete) break;

        packParser = Packet.Parse(packParser.RemainderData);
      }

      if (packParser.Completeness == PComplet.Incomplete)
        remaindData = packParser.RemainderData;

      return result;
    }

    public List<byte[]> HandlePacketInternal(Packet packParser)
    {
      List<byte[]> result = new List<byte[]>();
      List<string> dt = new List<string>();

      switch (packParser.Command)
      {
        case CMD.IT:
          var syn = new SN_Pack();
          syn.Data = "7054876344F77CAD468172501CC858F8C2EE4E3398DBDF026C317302223DD9D6".ToArr();
          syn.DataSize = (byte)syn.Data.Length;

          result.Add(syn.ToBytes());
          break;
        case CMD.SA:
          var ident = new ID_Pack();
          ident.Data = "CCAF7E1DBC98441E831BA510537C6D616656375C686975190712975F4341C6BC".ToArr();
          result.Add(ident.ToBytes());

          var a = new CK_Pack();
          // Публичная адаптация: CK payload предоставляется локально и не хранится в Git.
          var ckPath = System.IO.Path.Combine(Environment.CurrentDirectory, "private", "lobby-ck.bin");
          a.Data = System.IO.File.ReadAllBytes(ckPath);
          if (a.Data.Length != 32) throw new System.IO.InvalidDataException("Нужен локальный lobby-ck.bin длиной32байта");
          result.Add(a.ToBytes());

          break;
        case CMD.DT:
          var data = new DT_Pack();
          dt = new List<string>();

          if (!Init)
          {
            Init = true;
            dt.Add("");
            dt.Add("EA2F33C042DE68DE8FCFB5AD7698E18863BFAC2B6920B9819FC3328A508D391B");
            dt.Add("C62D1BC5ADEBF5D44336F2DBF3B6A0CEDF97814832EF1716680959B72FDC70516D41632611BD45E99A1BD58A55AD8771");
            dt.Add("5831FDAD811D99BD8681A0A9040011AB56D244ADA36A9C66BDEF60FAB3372A5C8F71736A260F0A60ACCBF10203B828A4");
          }

          foreach (string item in dt)
          {
            if (item == "") continue;

            data.Data = item.ToArr();
            result.Add(data.ToBytes());
          }

          break;
      }

      return result;
    }
  }
}
